//! Generated files, verified by reproduction.

use std::path::{Component, Path};
use std::time::Duration;

use super::target::is_object_id;
use super::{
    Failure, How, isolated_diff_env, pinned_diff_args, run_with_env, run_with_isolated_env,
};

/// The file at the repository root that declares generated files.
pub const DECLARATION_FILE: &str = "estigia.generated.toml";

const DEADLINE: Duration = Duration::from_secs(300);

#[cfg(test)]
mod tests;

/// One declared generated file: where it lives and the argv that regenerates it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Declaration {
    /// Repository-relative path of the generated file.
    pub path: String,
    /// The argv run, with no shell.
    pub command: Vec<String>,
    /// Repository-relative directory the command runs in.
    pub cwd: Option<String>,
}

/// What reproducing one declared path found.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Outcome {
    /// The regenerated bytes equal the head blob.
    Match,
    /// The command exited cleanly and wrote other bytes.
    Mismatch,
    /// The command could not be run to a comparable end.
    Unavailable(String),
    /// Reproduction was not asked for, so no declared command ran.
    NotRun,
    /// The change is a deletion or a mode change, which has no content to regenerate.
    FallsBackToHunks(&'static str),
}

/// One declared path the change touched, and what reproducing it found.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PathOutcome {
    /// Repository-relative path.
    pub path: String,
    /// What was found.
    pub outcome: Outcome,
}

fn malformed(detail: impl Into<String>) -> Failure {
    Failure::Stop(serde_json::json!({
        "ok": false,
        "reason": "generated-declaration-malformed",
        "detail": detail.into(),
        "action": "correct `estigia.generated.toml` on the base branch; a declaration is read \
                   only from the base, so a fix in the head does not count",
    }))
}

fn relative(label: &str, value: &str) -> Result<(), Failure> {
    let clean = !value.is_empty()
        && !value.contains('\\')
        && !value.chars().any(char::is_control)
        && Path::new(value)
            .components()
            .all(|component| matches!(component, Component::Normal(_)));
    if clean {
        Ok(())
    } else {
        Err(malformed(format!(
            "`{label}` must be a plain repository-relative path, got `{value}`"
        )))
    }
}

fn string_of(table: &toml_edit::Table, key: &str) -> Result<Option<String>, Failure> {
    match table.get(key) {
        None => Ok(None),
        Some(item) => item
            .as_str()
            .map(|text| Some(text.to_owned()))
            .ok_or_else(|| malformed(format!("`{key}` must be a string"))),
    }
}

fn declaration_of(table: &toml_edit::Table) -> Result<Declaration, Failure> {
    if let Some(unknown) = table
        .iter()
        .map(|(key, _)| key)
        .find(|key| !["path", "command", "cwd"].contains(key))
    {
        return Err(malformed(format!("`{unknown}` is not a known key")));
    }
    let path = string_of(table, "path")?.ok_or_else(|| malformed("a declaration needs `path`"))?;
    relative("path", &path)?;
    let cwd = string_of(table, "cwd")?;
    if let Some(cwd) = &cwd {
        relative("cwd", cwd)?;
    }
    let command: Vec<String> = table
        .get("command")
        .and_then(toml_edit::Item::as_array)
        .ok_or_else(|| malformed("`command` must be an array of strings"))?
        .iter()
        .map(|argument| argument.as_str().map(str::to_owned))
        .collect::<Option<_>>()
        .ok_or_else(|| malformed("`command` must be an array of strings"))?;
    if command.first().is_none_or(String::is_empty) {
        return Err(malformed("`command` must start with a program name"));
    }
    Ok(Declaration { path, command, cwd })
}

/// Parses the declaration file, refusing anything that could not run as written.
pub fn parse(text: &str) -> Result<Vec<Declaration>, Failure> {
    let document: toml_edit::DocumentMut = text
        .parse()
        .map_err(|error| malformed(format!("not valid TOML: {error}")))?;
    if let Some(unknown) = document
        .iter()
        .map(|(key, _)| key)
        .find(|key| *key != "generated")
    {
        return Err(malformed(format!("`{unknown}` is not a known table")));
    }
    let Some(item) = document.get("generated") else {
        return Ok(Vec::new());
    };
    let tables = item
        .as_array_of_tables()
        .ok_or_else(|| malformed("`generated` must be an array of tables, `[[generated]]`"))?;
    let mut declared: Vec<Declaration> = Vec::new();
    for table in tables {
        let one = declaration_of(table)?;
        if declared.iter().any(|seen| seen.path == one.path) {
            return Err(malformed(format!("`{}` is declared twice", one.path)));
        }
        declared.push(one);
    }
    Ok(declared)
}

fn declared_with(
    repo: &Path,
    base: &str,
    envs: &[(&str, &str)],
) -> Result<Vec<Declaration>, Failure> {
    if !is_object_id(base) {
        return Err(Failure::Read("the base is not an object id".to_owned()));
    }
    let listed = run_with_isolated_env(
        &[
            "git",
            "ls-tree",
            "--name-only",
            base,
            "--",
            DECLARATION_FILE,
        ],
        Some(repo),
        How::read(),
        envs,
    )?;
    if listed.stdout.trim().is_empty() {
        return Ok(Vec::new());
    }
    let spec = format!("{base}:{DECLARATION_FILE}");
    let content = run_with_isolated_env(
        &["git", "cat-file", "blob", &spec],
        Some(repo),
        How::read(),
        envs,
    )?;
    parse(&content.stdout)
}

fn borrowed(envs: &[(String, String)]) -> Vec<(&str, &str)> {
    envs.iter()
        .map(|(key, value)| (key.as_str(), value.as_str()))
        .collect()
}

/// The declarations the **base** commit carries; the working tree and the head
/// are never consulted.
pub fn declared_at(repo: &Path, base: &str) -> Result<Vec<Declaration>, Failure> {
    let (_guard, envs) = isolated_diff_env(repo)?;
    declared_with(repo, base, &borrowed(&envs))
}

struct Change {
    path: String,
    deleted: bool,
    base_mode: String,
    head_mode: String,
    base_blob: String,
    head_blob: String,
}

impl Change {
    fn falls_back(&self) -> Option<&'static str> {
        if self.deleted {
            Some("the path is deleted, so there is no content to regenerate")
        } else if self.base_mode != "000000" && self.base_mode != self.head_mode {
            Some("the mode changed, which regeneration does not reproduce")
        } else if !["100644", "100755"].contains(&self.head_mode.as_str()) {
            Some("the path is not a regular file, so there are no bytes to regenerate")
        } else {
            None
        }
    }
}

fn changes(
    repo: &Path,
    base: &str,
    head: &str,
    envs: &[(&str, &str)],
) -> Result<Vec<Change>, Failure> {
    let output = run_with_isolated_env(
        &pinned_diff_args(&["--raw", "--no-abbrev", "--no-renames", "-z", base, head]),
        Some(repo),
        How::read(),
        envs,
    )?;
    if output.stdout_replaced {
        return Err(Failure::Read(
            "git named a path that is not UTF-8".to_owned(),
        ));
    }
    let mut fields = output.stdout.split('\0').filter(|field| !field.is_empty());
    let mut found = Vec::new();
    while let Some(meta) = fields.next() {
        let path = fields
            .next()
            .ok_or_else(|| Failure::Read("git diff --raw ended inside a record".to_owned()))?;
        let parts: Vec<&str> = meta.trim_start_matches(':').split(' ').collect();
        let [old_mode, new_mode, base_blob, head_blob, status] = parts[..] else {
            return Err(Failure::Read(format!(
                "git diff --raw record unreadable: {meta}"
            )));
        };
        found.push(Change {
            path: path.to_owned(),
            deleted: status.starts_with('D'),
            base_mode: old_mode.to_owned(),
            head_mode: new_mode.to_owned(),
            base_blob: base_blob.to_owned(),
            head_blob: head_blob.to_owned(),
        });
    }
    Ok(found)
}

fn regenerate(
    repo: &Path,
    tree: &Path,
    declaration: &Declaration,
    change: &Change,
    envs: &[(&str, &str)],
    deadline: Duration,
) -> Outcome {
    let directory = declaration
        .cwd
        .as_deref()
        .map_or_else(|| tree.to_path_buf(), |cwd| tree.join(cwd));
    if !directory.is_dir() {
        return Outcome::Unavailable("the working directory is not in the head".to_owned());
    }
    let argv: Vec<&str> = declaration.command.iter().map(String::as_str).collect();
    let how = How {
        timeout: Some(deadline),
        ..How::tolerated()
    };
    match run_with_env(&argv, Some(&directory), how, &[]) {
        Err(failure) => return Outcome::Unavailable(failure.detail()),
        Ok(output) if output.status != 0 => {
            return Outcome::Unavailable(format!(
                "the command exited {}: {}",
                output.status,
                output.stderr.trim()
            ));
        }
        Ok(_) => {}
    }
    let produced = tree.join(&declaration.path);
    if !produced.is_file() {
        return Outcome::Unavailable("the command left no file at the declared path".to_owned());
    }
    let Some(produced) = produced.to_str() else {
        return Outcome::Unavailable("the declared path is not UTF-8".to_owned());
    };
    match run_with_isolated_env(
        &["git", "hash-object", "--no-filters", produced],
        Some(repo),
        How::read(),
        envs,
    ) {
        Ok(hashed) if hashed.stdout.trim() == change.head_blob => Outcome::Match,
        Ok(_) => Outcome::Mismatch,
        Err(failure) => Outcome::Unavailable(failure.detail()),
    }
}

fn materialise(
    repo: &Path,
    head: &str,
    tree: &Path,
    envs: &[(&str, &str)],
    index: &Path,
) -> Result<(), Failure> {
    std::fs::create_dir(tree)
        .map_err(|error| Failure::Read(format!("could not create {}: {error}", tree.display())))?;
    let tree_text = tree.display().to_string();
    let index_text = index.display().to_string();
    let mut scoped = envs.to_vec();
    scoped.push(("GIT_WORK_TREE", &tree_text));
    scoped.push(("GIT_INDEX_FILE", &index_text));
    for arguments in [
        vec!["git", "-c", "core.bare=false", "read-tree", head],
        vec![
            "git",
            "-c",
            "core.bare=false",
            "checkout-index",
            "--all",
            "--force",
        ],
    ] {
        run_with_isolated_env(&arguments, Some(repo), How::read(), &scoped)?;
    }
    Ok(())
}

/// Reproduces every base-declared path the change touches, in a scratch copy of
/// the head that is removed afterwards. The caller's worktree is never written.
pub fn reproduce(repo: &Path, base: &str, head: &str) -> Result<Vec<PathOutcome>, Failure> {
    evaluate(repo, base, head, true, DEADLINE)
}

fn evaluate(
    repo: &Path,
    base: &str,
    head: &str,
    run: bool,
    deadline: Duration,
) -> Result<Vec<PathOutcome>, Failure> {
    if !is_object_id(head) {
        return Err(Failure::Read("the head is not an object id".to_owned()));
    }
    let (guard, envs) = isolated_diff_env(repo)?;
    let envs = borrowed(&envs);
    let declared = declared_with(repo, base, &envs)?;
    if declared.is_empty() {
        return Ok(Vec::new());
    }
    let touched = changes(repo, base, head, &envs)?;
    let mut outcomes = Vec::new();
    for (position, declaration) in declared.iter().enumerate() {
        let Some(change) = touched
            .iter()
            .find(|change| change.path == declaration.path)
        else {
            continue;
        };
        let outcome = if !run {
            Outcome::NotRun
        } else if let Some(why) = change.falls_back() {
            Outcome::FallsBackToHunks(why)
        } else {
            let tree = guard.dir.join(format!("tree-{position}"));
            let index = guard.dir.join(format!("index-{position}"));
            match materialise(repo, head, &tree, &envs, &index) {
                Ok(()) => {
                    for each in &declared {
                        let _ = std::fs::remove_file(tree.join(&each.path));
                    }
                    regenerate(repo, &tree, declaration, change, &envs, deadline)
                }
                Err(failure) => Outcome::Unavailable(failure.detail()),
            }
        };
        outcomes.push(PathOutcome {
            path: declaration.path.clone(),
            outcome,
        });
    }
    Ok(outcomes)
}

/// A declared path whose hunks a payload replaces with one line, because the
/// gate regenerates its bytes before an approval is recorded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ManifestEntry {
    /// Repository-relative path of the generated file.
    pub path: String,
    /// Blob at the payload's base, all zeros for a file the change adds.
    pub base_blob: String,
    /// Blob at the head.
    pub head_blob: String,
    /// Size of the head blob.
    pub head_bytes: u64,
    /// The declaration's working directory.
    pub cwd: Option<String>,
    /// The declaration's argv.
    pub command: Vec<String>,
}

/// Prefix of the one line a manifest entry becomes in a payload.
pub const MANIFEST_PREFIX: &str = "# estigia-generated ";

impl ManifestEntry {
    /// `diff --git` header and manifest line, in the shape `docs/generated-files.md` documents.
    pub fn block(&self) -> String {
        let json = |value: serde_json::Value| value.to_string();
        format!(
            "diff --git a/{path} b/{path}\n{MANIFEST_PREFIX}{{\"path\":{p},\"base-blob\":{b},\"head-blob\":{h},\"head-bytes\":{n},\"cwd\":{c},\"command\":{k}}}\n",
            path = self.path,
            p = json(serde_json::json!(self.path)),
            b = json(serde_json::json!(self.base_blob)),
            h = json(serde_json::json!(self.head_blob)),
            n = self.head_bytes,
            c = json(serde_json::json!(self.cwd)),
            k = json(serde_json::json!(self.command)),
        )
    }
}

struct Eligible {
    declaration: Declaration,
    base_blob: String,
    head_blob: String,
}

fn eligible(
    repo: &Path,
    authority: &str,
    base: &str,
    head: &str,
    envs: &[(&str, &str)],
) -> Result<Vec<Eligible>, Failure> {
    if !is_object_id(head) {
        return Err(Failure::Read("the head is not an object id".to_owned()));
    }
    let declared = declared_with(repo, authority, envs)?;
    if declared.is_empty() {
        return Ok(Vec::new());
    }
    let authorised = changes(repo, authority, head, envs)?;
    let ranged = if authority == base {
        None
    } else {
        Some(changes(repo, base, head, envs)?)
    };
    let mut found = Vec::new();
    for declaration in declared {
        let find = |from: &[Change]| {
            from.iter()
                .position(|change| change.path == declaration.path)
        };
        let Some(by_authority) = find(&authorised) else {
            continue;
        };
        if authorised[by_authority].falls_back().is_some() {
            continue;
        }
        let ranged_view = ranged.as_deref().unwrap_or(&authorised);
        let Some(in_range) = find(ranged_view).map(|at| &ranged_view[at]) else {
            continue;
        };
        if in_range.falls_back().is_some() {
            continue;
        }
        found.push(Eligible {
            base_blob: in_range.base_blob.clone(),
            head_blob: in_range.head_blob.clone(),
            declaration,
        });
    }
    Ok(found)
}

/// The declared paths a payload over `base..head` shows as manifest lines.
///
/// A path qualifies only when `authority` declares it and the change
/// `authority..head` adds or modifies it as a regular file; `authority` is the
/// receipt's base even when `base` is a repair's parent, so a declaration the
/// change itself introduced never turns hunks into a line nobody regenerates.
pub fn manifest_entries(
    repo: &Path,
    authority: &str,
    base: &str,
    head: &str,
    envs: &[(&str, &str)],
) -> Result<Vec<ManifestEntry>, Failure> {
    let mut entries = Vec::new();
    for one in eligible(repo, authority, base, head, envs)? {
        let sized = run_with_isolated_env(
            &["git", "cat-file", "-s", &one.head_blob],
            Some(repo),
            How::read(),
            envs,
        )?;
        let head_bytes = sized.stdout.trim().parse::<u64>().map_err(|_| {
            Failure::Read(format!(
                "git cat-file -s answered {:?}",
                sized.stdout.trim()
            ))
        })?;
        entries.push(ManifestEntry {
            path: one.declaration.path,
            base_blob: one.base_blob,
            head_blob: one.head_blob,
            head_bytes,
            cwd: one.declaration.cwd,
            command: one.declaration.command,
        });
    }
    entries.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(entries)
}

/// The paths a payload over `base..head` shows as manifest lines, sorted.
///
/// The one rule for what a reviewer is not shown as hunks, shared with
/// [`manifest_entries`]: the tier and the correction budget read it so they
/// never count lines nobody is shown.
pub fn manifested_paths(
    repo: &Path,
    authority: &str,
    base: &str,
    head: &str,
) -> Result<Vec<String>, Failure> {
    let (_guard, envs) = isolated_diff_env(repo)?;
    let mut paths: Vec<String> = eligible(repo, authority, base, head, &borrowed(&envs))?
        .into_iter()
        .map(|one| one.declaration.path)
        .collect();
    paths.sort();
    Ok(paths)
}

/// Regenerates every manifest path of `base..head` and refuses unless each one matches.
///
/// Returns how many paths were regenerated. Run it only where running
/// repository code is the operation's point; a read never calls it.
pub fn require_reproduction(repo: &Path, base: &str, head: &str) -> Result<usize, Failure> {
    require_reproduction_within(repo, base, head, DEADLINE)
}

pub(crate) fn require_reproduction_within(
    repo: &Path,
    base: &str,
    head: &str,
    deadline: Duration,
) -> Result<usize, Failure> {
    let verified: Vec<PathOutcome> = evaluate(repo, base, head, true, deadline)?
        .into_iter()
        .filter(|found| !matches!(found.outcome, Outcome::FallsBackToHunks(_)))
        .collect();
    let failed: Vec<&PathOutcome> = verified
        .iter()
        .filter(|found| found.outcome != Outcome::Match)
        .collect();
    if failed.is_empty() {
        return Ok(verified.len());
    }
    let mismatched = failed
        .iter()
        .any(|found| found.outcome == Outcome::Mismatch);
    let paths: Vec<serde_json::Value> = failed.iter().map(|found| found.to_json()).collect();
    Err(Failure::Stop(if mismatched {
        serde_json::json!({
            "ok": false,
            "reason": "generated-reproduction-mismatch",
            "paths": paths,
            "action": "regenerate each named file with its declared command, commit the result \
                       and publish again; an approval over bytes nobody regenerated is not \
                       recorded",
        })
    } else {
        serde_json::json!({
            "ok": false,
            "reason": "generated-reproduction-unavailable",
            "paths": paths,
            "action": "the declared command could not be run to a comparable end, which is not \
                       a match; make it runnable here or change the declaration on the base \
                       branch, then record the verdict again",
        })
    }))
}

impl PathOutcome {
    fn to_json(&self) -> serde_json::Value {
        let path = &self.path;
        match &self.outcome {
            Outcome::Match => serde_json::json!({"path": path, "outcome": "match"}),
            Outcome::NotRun => serde_json::json!({
                "path": path,
                "outcome": "not-run",
                "action": "pass `reproduce: true` to run the base-declared command; it executes \
                           repository code and may use the network",
            }),
            Outcome::Mismatch => serde_json::json!({
                "path": path,
                "outcome": "mismatch",
                "reason": "generated-reproduction-mismatch",
                "action": "the committed bytes are not what the declared command produces from \
                           the head; regenerate the file with that command and commit the result, \
                           or review the file's hunks as ordinary text",
            }),
            Outcome::Unavailable(detail) => serde_json::json!({
                "path": path,
                "outcome": "unavailable",
                "reason": "generated-reproduction-unavailable",
                "detail": detail,
                "action": "the declared command could not be run to a comparable end; this is not \
                           a match. Review the file's hunks as ordinary text",
            }),
            Outcome::FallsBackToHunks(why) => serde_json::json!({
                "path": path,
                "outcome": "falls-back-to-hunks",
                "detail": why,
            }),
        }
    }
}

/// The reproduction answer a read-only review read carries. With `run` unset
/// nothing is executed and each touched declared path reads `not-run`. It decides nothing:
/// a refusal or a failure is reported inside it, never raised.
pub fn report(repo: &Path, base: &str, head: &str, run: bool) -> serde_json::Value {
    match evaluate(repo, base, head, run, DEADLINE) {
        Ok(outcomes) => serde_json::json!({
            "outcomes": outcomes.iter().map(PathOutcome::to_json).collect::<Vec<_>>(),
        }),
        Err(Failure::Stop(payload)) => serde_json::json!({"outcomes": [], "refusal": payload}),
        Err(failure) => serde_json::json!({
            "outcomes": [],
            "refusal": {
                "ok": false,
                "reason": "generated-reproduction-unavailable",
                "detail": failure.detail(),
                "action": "the declaration or the repository could not be read; review the \
                           change's hunks as ordinary text",
            },
        }),
    }
}
